55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const basePremiumOf = (item: Item): number =>
67	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
68	
69	const policyBasePremiumOf = (items: readonly Item[]): number =>
70	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
71	
72	export function runScenario(scenario: Scenario): ScenarioResult {
73	  const quoteStep = scenario.steps[0] as QuoteStep;
74	  const premium = policyBasePremiumOf(quoteStep.items) + PROCESSING_FEE;
75	  return { results: [{ premium }] };
76	}
