const quotePremiumOf = (items: readonly Item[]): number =>
  policyBasePremiumOf(items) + PROCESSING_FEE;

export function runScenario(scenario: Scenario): ScenarioResult {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremiumOf(quoteStep.items) }] };
}
